  S.action('builder-confirm-publish',()=>{const form=document.getElementById('builder-publish-form');if(!S.validate(form,{version:value=>/^\d+\.\d+(?:\.\d+)?$/.test(value)?null:'请使用数字版本号，例如 1.1 或 1.1.0'}))return;const f=current(),version=form.elements.namedItem('version').value.trim();if((f.history||[]).some(h=>h.version===version)){const input=form.elements.namedItem('version');const errorEl=document.getElementById(input.id+'-error');errorEl.textContent='这个版本号已经发布，请使用新版本号。';input.focus();return;}f.version=version;f.published=true;f.publishedSnapshot=R.snapshot(f);f.versions=f.versions||[];f.versions.push(clone(f.publishedSnapshot));f.history=f.history||[];f.history.unshift({version,note:form.elements.namedItem('note').value.trim()||'发布工作流配置',date:when(Date.now()),snapshot:clone(f.publishedSnapshot)});ui.drafts[f.id]=clone(f);S.save();markDirty();S.closeModal();refresh();S.toast('已发布 v'+version);});
