  S.action('builder-auto-layout',()=>{change(d=>{const depth=new Map();d.nodes.forEach(n=>depth.set(n.id,0));for(let i=0;i<d.nodes.length;i++){let changed=false;d.edges.forEach(e=>{const a=depth.get(e.source)||0,b=depth.get(e.target)||0;if(a+1>b){depth.set(e.target,Math.min(a+1,d.nodes.length));changed=true;}});if(!changed)break;}const lanes={};d.nodes.forEach(n=>{const level=depth.get(n.id)||0;const lane=lanes[level]||0;lanes[level]=lane+1;n.x=48+level*294;n.y=60+lane*210;});});S.toast('已按控制依赖整理节点位置');});
