  S.action('builder-add-binding',el=>{ui.bindingPrefix=el?.dataset?.prefix||'bindings';S.modal({title:'添加输入参数',subtitle:'字段名用于节点输入；在最终输出节点中也作为返回字段名。',body:`<form novalidate id="builder-add-binding-form" data-form="builder-binding">${S.field('字段名称',{id:'builder-new-binding-name',name:'name',required:true,placeholder:'例如 summary'})}<div class="field"><label class="field-label" for="builder-new-binding-type">值类型</label><select class="select" id="builder-new-binding-type" name="type"><option>string</option><option>number</option><option>boolean</option><option>object</option><option>array</option></select></div></form>`,footer:button('取消','modal-close')+S.btn('添加字段','builder-confirm-binding')});});
  S.form('builder-binding',()=>S.actions['builder-confirm-binding']());
  S.action('builder-confirm-binding',()=>{const form=document.getElementById('builder-add-binding-form');if(!S.validate(form,{name:v=>/^[A-Za-z_][\w-]*$/.test(v)&&!['__proto__','constructor','prototype'].includes(v)?null:'使用字母或下划线开头的字段名'}))return;const name=form.elements.namedItem('name').value.trim(),type=form.elements.namedItem('type').value;if(Object.prototype.hasOwnProperty.call(bindingOwner(selected(),ui.bindingPrefix),name)){document.getElementById('builder-new-binding-name-error').textContent='这个字段名已经存在。';return;}change(()=>{bindingOwner(selected(),ui.bindingPrefix)[name]={mode:'constant',value:({string:'',number:0,boolean:false,object:{},array:[]})[type]};});S.closeModal();});
